37	/**
38	 * Rejects creating an owner whose E.164 telephone is already used by another owner,
39	 * answering 409. Kept as its own advice so this rule stays a small, self-contained unit
40	 * rather than growing the controller or another handler.
41	 */
42	@ControllerAdvice
43	@Order(Ordered.HIGHEST_PRECEDENCE)
44	public class OwnerUniqueTelephoneAdvice extends RequestBodyAdviceAdapter {
45	
46	    private final ClinicService clinicService;
47	
48	    public OwnerUniqueTelephoneAdvice(ClinicService clinicService) {
49	        this.clinicService = clinicService;
50	    }
51	
52	    @Override
53	    public boolean supports(MethodParameter methodParameter, Type targetType,
